// Backslash escapes the next character. Returns the index just past the
// closing quote, or -1 when unterminated.
function skipAnsiC(src: string, quote: number): number {
  const n = src.length
  let i = quote + 1
  while (i < n) {
    const c = src.charAt(i)
    if (c === '\\') {
      i += 2
      continue
    }
    if (c === "'") return i + 1
    i++
